import heapq


def plan(tasks, target):
    if target not in tasks:
        raise ValueError(f'Unknown target: {target}')

    needed = set()
    pending = [target]
    prerequisites = {}
    while pending:
        name = pending.pop()
        if name in needed:
            continue
        needed.add(name)
        deps = set(tasks[name])
        for dep in deps:
            if dep not in tasks:
                raise ValueError(f'Unknown prerequisite {dep} for {name}')
        prerequisites[name] = deps
        pending.extend(deps)

    dependents = {name: set() for name in needed}
    indegree = {name: len(prerequisites[name]) for name in needed}
    for name, deps in prerequisites.items():
        for dep in deps:
            dependents[dep].add(name)

    ready = [name for name in needed if indegree[name] == 0]
    heapq.heapify(ready)
    result = []
    while ready:
        name = heapq.heappop(ready)
        result.append(name)
        for child in dependents[name]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    if len(result) != len(needed):
        raise ValueError('Dependency cycle')
    return result


def raises(fn):
    try:
        fn()
    except ValueError:
        return
    raise AssertionError('expected ValueError')


if __name__ == '__main__':
    diamond = {'app': ['api', 'ui'], 'api': ['core'],
               'ui': ['core'], 'core': []}
    assert plan(diamond, 'app') == ['core', 'api', 'ui', 'app']
    assert plan({'app': ['core'], 'core': [],
                 'x': ['y'], 'y': ['x']}, 'app') == ['core', 'app']
    raises(lambda: plan({'a': ['b'], 'b': ['a']}, 'a'))
    raises(lambda: plan({'a': ['missing']}, 'a'))
    assert plan({'a': ['b', 'b'], 'b': []}, 'a') == ['b', 'a']
```

- `CycleError` is a `ValueError` subclass with a `cycle` attribute containing a closed path: the first and last names are equal, and each successive pair follows a task → prerequisite edge.
- Only the target’s prerequisite closure is checked. Duplicate edges count once, and a min-heap picks the lexically smallest currently available task. The cycle search also visits names in lexical order so its reported path is reproducible.

```python
import heapq


class CycleError(ValueError):
    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__('Dependency cycle: ' + ' -> '.join(self.cycle))


def plan(tasks, target):
    if target not in tasks:
        raise ValueError(f'Unknown target: {target}')

    # Collect and validate only the reachable prerequisite closure.
    prerequisites = {}
    pending = [target]
    while pending:
        name = pending.pop()
        if name in prerequisites:
            continue
        deps = set(tasks[name])
        for dep in sorted(deps):
            if dep not in tasks:
                raise ValueError(f'Unknown prerequisite {dep} for {name}')
        prerequisites[name] = deps
        pending.extend(deps)

    dependents = {name: set() for name in prerequisites}
    indegree = {name: len(deps) for name, deps in prerequisites.items()}
    for name, deps in prerequisites.items():
        for dep in deps:
            dependents[dep].add(name)

    ready = [name for name, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    result = []
    while ready:
        name = heapq.heappop(ready)
        result.append(name)
        for child in dependents[name]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)

    if len(result) == len(prerequisites):
        return result

    # Iterative DFS finds a back edge and reconstructs a closed cycle.
    # 0 = unseen, 1 = on the current path, 2 = finished.
    color = {name: 0 for name in prerequisites}
    path = []
    position = {}
    for root in sorted(prerequisites):
        if color[root]:
            continue
        color[root] = 1
        position[root] = len(path)
        path.append(root)
        stack = [(root, iter(sorted(prerequisites[root])))]
        while stack:
            name, edges = stack[-1]
            dep = next(edges, None)
            if dep is None:
                stack.pop()
                path.pop()
                del position[name]
                color[name] = 2
            elif color[dep] == 1:
                raise CycleError(path[position[dep]:] + [dep])
            elif color[dep] == 0:
                color[dep] = 1
                position[dep] = len(path)
                path.append(dep)
                stack.append((dep, iter(sorted(prerequisites[dep]))))

    raise AssertionError('cycle expected after incomplete topological sort')


def expect_value_error(fn):
    try:
        fn()
    except CycleError:
        raise AssertionError('expected a non-cycle ValueError')
    except ValueError:
        return
    raise AssertionError('expected ValueError')


def check_cycle(tasks, target):
    try:
        plan(tasks, target)
    except CycleError as exc:
        cycle = exc.cycle
        assert len(cycle) >= 2 and cycle[0] == cycle[-1]
        for task, dependency in zip(cycle, cycle[1:]):
            assert dependency in tasks[task], (task, dependency)
        return cycle
    raise AssertionError('expected CycleError')


if __name__ == '__main__':
    tasks = {
        'app': ['api', 'ui', 'api'],
        'api': ['core'],
        'ui': ['core'],
        'core': [],
        'x': ['y'],
        'y': ['x'],
    }
    assert plan(tasks, 'app') == ['core', 'api', 'ui', 'app']
    assert check_cycle(tasks, 'x') == ['x', 'y', 'x']
    assert check_cycle({'a': ['a']}, 'a') == ['a', 'a']
    check_cycle({'app': ['a'], 'a': ['b'], 'b': ['a']}, 'app')
    expect_value_error(lambda: plan({'app': ['missing']}, 'app'))
    expect_value_error(lambda: plan({'app': []}, 'missing'))

    # Choose from all currently available tasks, not just DFS siblings.
    assert plan({'app': ['b', 'z'], 'b': ['a'], 'a': [], 'z': []},
                'app') == ['a', 'b', 'z', 'app']
