def merge(cues):
    """Merge sorted half-open cues without changing the input.

    Labels in each merged group retain their first input occurrence.
    Zero-length cues remain separate, even inside another interval.
    """
    finished = []  # (start, original position, result)
    current = None
    previous_start = None

    for position, cue in enumerate(cues):
        start, end, label = cue['start'], cue['end'], cue['label']
        if not isinstance(start, int) or isinstance(start, bool):
            raise ValueError('start must be an integer')
        if not isinstance(end, int) or isinstance(end, bool):
            raise ValueError('end must be an integer')
        if not isinstance(label, str):
            raise ValueError('label must be a string')
        if start > end:
            raise ValueError('start must not exceed end')
        if previous_start is not None and start < previous_start:
            raise ValueError('cues must be sorted by start')
        previous_start = start

        if start == end:
            finished.append((start, position, {
                'start': start, 'end': end, 'label': label
            }))
            continue

        if current is not None and start < current['end']:
            current['end'] = max(current['end'], end)
            if label not in current['labels']:
                current['labels'].append(label)
        else:
            if current is not None:
                finished.append((current['start'], current['position'], {
                    'start': current['start'], 'end': current['end'],
                    'label': ','.join(current['labels'])
                }))
            current = {
                'start': start, 'end': end, 'position': position,
                'labels': [label]
            }

    if current is not None:
        finished.append((current['start'], current['position'], {
            'start': current['start'], 'end': current['end'],
            'label': ','.join(current['labels'])
        }))

    finished.sort(key=lambda item: (item[0], item[1]))
    return [result for _, _, result in finished]
```

Zero-length cues are collected separately, so they cannot interrupt an overlapping group. Results are ordered by start time, with input order breaking ties.

