def merge(cues):
    """Merge overlapping half-open cues without mutating the input."""
    ordered = []
    for pos, cue in enumerate(cues):
        start, end, label = cue['start'], cue['end'], cue['label']
        if type(start) is not int or type(end) is not int:
            raise ValueError('times must be integers')
        if not isinstance(label, str):
            raise ValueError('label must be a string')
        if start > end:
            raise ValueError('start must not exceed end')
        ordered.append((start, pos, end, label))

    ordered.sort(key=lambda item: (item[0], item[1]))
    finished = []
    current = None

    def finish(group):
        labels = []
        seen = set()
        for _, label in sorted(group['labels']):
            if label not in seen:
                seen.add(label)
                labels.append(label)
        finished.append((group['start'], group['position'], {
            'start': group['start'], 'end': group['end'],
            'label': ','.join(labels)
        }))

    for start, pos, end, label in ordered:
        if start == end:
            finished.append((start, pos, {
                'start': start, 'end': end, 'label': label
            }))
        elif current is not None and start < current['end']:
            current['end'] = max(current['end'], end)
            current['labels'].append((pos, label))
        else:
            if current is not None:
                finish(current)
            current = {'start': start, 'end': end, 'position': pos,
                       'labels': [(pos, label)]}

    if current is not None:
        finish(current)
    finished.sort(key=lambda item: (item[0], item[1]))
    return [result for _, _, result in finished]
```

For input `[{'start': 5, 'end': 10, 'label': 'B'}, {'start': 0, 'end': 7, 'label': 'A'}]`, chronological order is A then B, but the merged result is `{'start': 0, 'end': 10, 'label': 'B,A'}` because labels follow original input order. Zero-length cues remain standalone and do not interrupt a merged group.
